import { readFileSync } from 'node:fs'
import { parse } from './parse.js'
import { count } from './count.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}
let election
try {
  election = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!e.isInputError) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
const { rounds, winner } = count(election)
let out = ''
if (mode === 'rounds') {
  rounds.forEach((r, i) => {
    out += `round ${i + 1}: ${r.list.map(([n, v]) => `${n}=${v}`).join(' ')} exhausted=${r.exhausted}\n`
    if (r.eliminated !== null) out += `eliminated ${r.eliminated}\n`
  })
} else out += `rounds ${rounds.length}\n`
out += winner === null ? 'no winner\n' : `winner ${winner}\n`
process.stdout.write(out)
EOF
cat > src/parse.js <<'EOF'
const fail = (m) => Object.assign(new Error(m), { isInputError: true })
const NAME = /^[A-Za-z0-9_-]+$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  lines.forEach((raw, idx) => {
    const n = idx + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (candidates !== null || ballots.length > 0) throw fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) throw fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) throw fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (candidates === null) throw fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) throw fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) throw fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) throw fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else throw fail(`error: line ${n}: unknown directive ${t[0]}`)
  })
  if (candidates === null) throw fail('error: no candidates')
  return { candidates, ballots }
}
EOF
cat > src/count.js <<'EOF'
export function count({ candidates, ballots }) {
  const alive = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...alive].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => alive.has(p))
      if (c !== undefined) { votes.set(c, votes.get(c) + b.count); active += b.count }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const [c, v] of votes) history.get(c).push(v)
    const list = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : 1))
    const round = { list, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [c, v] of list) if (v * 2n > active) return { rounds, winner: c }
    const min = list.reduce((m, [, v]) => (v < m ? v : m), list[0][1])
    let tied = list.filter(([, v]) => v === min).map(([c]) => c)
    for (let r = 0; tied.length > 1 && r < rounds.length; r++) {
      const m = tied.reduce((a, c) => (history.get(c)[r] < a ? history.get(c)[r] : a), history.get(tied[0])[r])
      tied = tied.filter((c) => history.get(c)[r] === m)
    }
    const out = tied.sort()[tied.length - 1]
    alive.delete(out)
    round.eliminated = out
  }
}
EOF
